N = {"t": 0}


def cap(title):
    N["t"] += 1
    return "Таблица %d – %s\n\n" % (N["t"], title)


def tbl(head, rows):
    out = "| " + " | ".join(head) + " |\n|" + "---|" * len(head) + "\n"
    for r in rows:
        out += "| " + " | ".join(str(x) for x in r) + " |\n"
    return out + "\n"


def f2(x):
    return str(round(x, 2)).replace(".", ",")


def cut(t, n=170):
    return t if len(t) <= n else t[:n].rstrip() + "…"


